(() => {
  const Z=window.Zucco,{state,icon:I,avatar:A,btn:BT}=Z;
  const HOUR_HEIGHT=48, START_HOUR=8, HOURS=12;
  const EVENTS=[
    {day:0,start:9,duration:1.5,course:'IELTS Foundation',type:'ielts',teacher:'Madina Karimova',short:'Madina K.',room:'201',students:12,capacity:16},
    {day:0,start:12,duration:2,course:'Frontend Dev.',type:'frontend',teacher:'Sardor Tursunov',short:'Sardor T.',room:'Lab 01',students:14,capacity:16},
    {day:0,start:16,duration:1.5,course:'General English',type:'english',teacher:'Aziza Rahimova',short:'Aziza R.',room:'202',students:10,capacity:14},
    {day:1,start:8,duration:1.5,course:'General English',type:'english',teacher:'Aziza Rahimova',short:'Aziza R.',room:'202',students:11,capacity:14},
    {day:1,start:11,duration:2,course:'Mathematics',type:'math',teacher:'Jasur Aliyev',short:'Jasur A.',room:'103',students:15,capacity:18},
    {day:1,start:15,duration:1.5,course:'Mathematics',type:'math',teacher:'Jasur Aliyev',short:'Jasur A.',room:'103',students:12,capacity:16},
    {day:2,start:9,duration:1.5,course:'IELTS Foundation',type:'ielts',teacher:'Madina Karimova',short:'Madina K.',room:'201',students:12,capacity:16},
    {day:2,start:13,duration:2,course:'Frontend Dev.',type:'frontend',teacher:'Sardor Tursunov',short:'Sardor T.',room:'Lab 01',students:14,capacity:16},
    {day:2,start:17,duration:1.5,course:'General English',type:'english',teacher:'Aziza Rahimova',short:'Aziza R.',room:'202',students:10,capacity:14},
    {day:3,start:8,duration:1.5,course:'General English',type:'english',teacher:'Aziza Rahimova',short:'Aziza R.',room:'202',students:11,capacity:14},
    {day:3,start:11,duration:2,course:'Mathematics',type:'math',teacher:'Jasur Aliyev',short:'Jasur A.',room:'103',students:15,capacity:18},
    {day:3,start:15,duration:1.5,course:'Mathematics',type:'math',teacher:'Jasur Aliyev',short:'Jasur A.',room:'103',students:12,capacity:16},
    {day:4,start:9,duration:1.5,course:'IELTS Foundation',type:'ielts',teacher:'Madina Karimova',short:'Madina K.',room:'201',students:12,capacity:16},
    {day:4,start:12,duration:2,course:'Frontend Dev.',type:'frontend',teacher:'Sardor Tursunov',short:'Sardor T.',room:'Lab 01',students:14,capacity:16},
    {day:4,start:17,duration:1.5,course:'General English',type:'english',teacher:'Aziza Rahimova',short:'Aziza R.',room:'202',students:10,capacity:14},
    {day:5,start:10,duration:2,course:'IELTS Mock Exam',type:'ielts',teacher:'Madina Karimova',short:'Madina K.',room:'201',students:16,capacity:16},
    {day:5,start:15,duration:1.5,course:'Mathematics',type:'math',teacher:'Jasur Aliyev',short:'Jasur A.',room:'103',students:12,capacity:16}
  ];
  const time = n=>`${String(Math.floor(n)).padStart(2,'0')}:${n%1?'30':'00'}`;
  function event(e,index){return `<button type="button" class="calendar-event ${e.type}" style="top:${(e.start-START_HOUR)*HOUR_HEIGHT+3}px;height:${e.duration*HOUR_HEIGHT-6}px" data-action="lesson:${index}" aria-label="${e.course}, ${e.teacher}, room ${e.room}, ${time(e.start)} to ${time(e.start+e.duration)}, ${e.students} of ${e.capacity} students"><h3>${e.course}</h3>${e.duration>=2?`<span class="event-time mono">${time(e.start)} – ${time(e.start+e.duration)}</span>`:''}<span class="event-teacher">${A(e.teacher,'','small')}${e.short}</span><span class="event-room mono"><span>Room ${e.room}</span><span>${e.students}/${e.capacity} students</span></span></button>`;}
  const date=day=>new Date(Date.UTC(2026,10,2+state.weekOffset*7+day));
  const dayName=day=>['Mon','Tue','Wed','Thu','Fri','Sat'][day];
  Z.renderers[Z.ROUTES.SCHEDULE]=()=>Z.heading('Weekly schedule','Every class, teacher, and classroom. One clear view.',BT('Export week','export-schedule','download')+BT('Schedule a class','new-lesson','plus','primary'))+
    `<div class="calendar-tools">${BT('Today','week-today')}<button type="button" class="icon-btn" data-action="week-prev" aria-label="Previous week">${I('left')}</button><button type="button" class="icon-btn" data-action="week-next" aria-label="Next week">${I('chevron')}</button><strong class="week-label">${new Intl.DateTimeFormat('en-US',{month:'short',timeZone:'UTC'}).format(date(0))} ${date(0).getUTCDate()} – ${date(5).getUTCDate()}, ${date(0).getUTCFullYear()}</strong><span class="caption">${EVENTS.length} classes</span><div class="grow"></div><select class="select" id="schedule-course" aria-label="Filter schedule course"><option value="all">All courses</option>${[['ielts','IELTS'],['english','General English'],['math','Mathematics'],['frontend','Frontend']].map(([id,label])=>`<option value="${id}" ${state.scheduleCourse===id?'selected':''}>${label}</option>`).join('')}</select><div class="segmented" aria-label="Calendar view"><button type="button" class="${state.scheduleMode==='week'?'active':''}" data-action="schedule-mode:week" aria-pressed="${state.scheduleMode==='week'}">Week</button><button type="button" class="${state.scheduleMode==='rooms'?'active':''}" data-action="schedule-mode:rooms" aria-pressed="${state.scheduleMode==='rooms'}">Rooms</button></div></div>${calendar()}
    <div class="schedule-footer"><div class="legend">${[['ielts','IELTS'],['english','General English'],['math','Mathematics'],['frontend','Frontend']].map(([type,label])=>`<span class="legend-item"><span class="legend-color ${type}"></span>${label}</span>`).join('')}</div><span class="schedule-note">Tashkent time · GMT+5</span></div>`;
  function calendar(){
    const rooms=['201','202','103','Lab 01'];
    const roomMode=state.scheduleMode==='rooms';
    const n=roomMode?4:6;
    const gridStyle=roomMode?'style="grid-template-columns:58px repeat(4,minmax(0,1fr))"':'';
    return `<div class="schedule-scroll"><section class="panel calendar-panel" aria-label="${roomMode?'Monday classroom timetable':'Monday to Saturday timetable'}" data-component="Timetable"><div class="calendar-days" ${gridStyle}><div class="timezone">GMT+5</div>${Array.from({length:n},(_,i)=>roomMode?`<div class="day-header"><span>${rooms[i]==='Lab 01'?'Computer lab':'Room '+rooms[i]}</span></div>`:`<div class="day-header ${i===0&&state.weekOffset===0?'today':''}"><span>${dayName(i).toUpperCase()}</span><strong>${date(i).getUTCDate()}</strong></div>`).join('')}</div><div class="calendar-body"><div class="time-axis">${Array.from({length:HOURS+1},(_,i)=>`<span class="time-label mono" style="top:${i*HOUR_HEIGHT}px">${time(START_HOUR+i)}</span>`).join('')}</div><div class="week-grid" ${roomMode?'style="grid-template-columns:repeat(4,minmax(0,1fr))"':''}>${Array.from({length:n},(_,i)=>`<div class="day-column ${i===0&&state.weekOffset===0?'today':''}">${EVENTS.map((e,j)=>({e,j})).filter(({e})=>(roomMode?e.day===0&&e.room===rooms[i]:e.day===i)&&(state.scheduleCourse==='all'||e.type===state.scheduleCourse)).map(({e,j})=>event(e,j)).join('')}</div>`).join('')}</div></div></section></div>`;
  }
  Z.showLesson=index=>{const e=EVENTS[index];Z.actionDialog(`<div class="dialog-body"><div class="dialog-title-row"><h2 id="action-title">${e.course}</h2>${BT('','close-action','close','ghost small')}</div><p>Lesson details · ${dayName(e.day)}, ${date(e.day).getUTCDate()} November</p><div class="conversion-details"><div class="detail-row"><span>Teacher</span><strong>${e.teacher}</strong></div><div class="detail-row"><span>Time</span><strong class="mono">${time(e.start)} – ${time(e.start+e.duration)}</strong></div><div class="detail-row"><span>Classroom</span><strong>Room ${e.room}</strong></div><div class="detail-row"><span>Capacity</span><strong>${e.students} / ${e.capacity} students</strong></div></div></div><div class="dialog-footer">${BT('Close','close-action')}${BT('Open attendance','lesson-attendance','book','primary')}</div>`);};
  Z.exportSchedule=download=>download('zucco-weekly-schedule.csv',[['Day','Course','Teacher','Room','Start','End','Students','Capacity'],...EVENTS.map(e=>[dayName(e.day),e.course,e.teacher,e.room,time(e.start),time(e.start+e.duration),e.students,e.capacity])]);
  Z.newLessonForm=()=>Z.actionDialog(`<form id="lesson-form"><div class="dialog-body"><h2 id="action-title">Schedule a class</h2><p>Add a class to this week’s timetable.</p><div class="action-form"><label class="stack"><span class="field-label">Course</span><select class="select" name="course"><option>IELTS Foundation</option><option>Mathematics</option><option>General English</option><option>Frontend Dev.</option></select></label><label class="stack"><span class="field-label">Day</span><select class="select" name="day">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((d,i)=>`<option value="${i}">${d}</option>`).join('')}</select></label><div class="row"><label class="stack grow"><span class="field-label">Start</span><input class="input" type="time" name="start" required min="08:00" max="19:00" value="18:00"></label><label class="stack grow"><span class="field-label">End</span><input class="input" type="time" name="end" required min="09:00" max="20:00" value="20:00"></label></div><label class="stack"><span class="field-label">Room</span><select class="select" name="room"><option>201</option><option>202</option><option>103</option><option>Lab 01</option></select></label><p id="lesson-error" class="amount-error" role="alert" hidden></p></div></div><div class="dialog-footer">${BT('Cancel','close-action')}<button class="btn primary" type="submit">Schedule class</button></div></form>`);
  Z.saveNewLesson=values=>{const parse=t=>Number(t.split(':')[0])+Number(t.split(':')[1])/60;const start=parse(String(values.get('start'))),end=parse(String(values.get('end'))),day=Number(values.get('day')),room=String(values.get('room'));const error=document.getElementById('lesson-error');if(end-start<1.5||EVENTS.some(e=>e.day===day&&e.room===room&&start<e.start+e.duration&&end>e.start)){error.hidden=false;error.textContent='Choose at least 90 minutes and a classroom without an overlapping class.';return;}const course=String(values.get('course')),type=course==='Mathematics'?'math':course==='General English'?'english':course==='Frontend Dev.'?'frontend':'ielts';EVENTS.push({day,start,duration:end-start,room,course,type,teacher:'Madina Karimova',short:'Madina K.',students:0,capacity:16});Z.closeAction();Z.render();Z.toast('Class added to the weekly schedule');};
})();
